float4 n_source_color_value = float4(0.200000003f, 0.400000006f, 0.600000024f, 0.800000012f);
float n_source_factor_value = 0.5f;
float4 n_inverted_result = lerp(n_source_color_value, (float4(1.0f, 1.0f, 1.0f, 1.0f) - n_source_color_value), saturate(n_source_factor_value));
return n_inverted_result;
